__NUXT_JSONP__("/th/about", (function(a,b){return {data:[{details:{slug:"th",pageTitle:"ทำความรู้จักกับ MLI | Mentor Language Institute",pageDescription:b,section1:{title:"ทำความรู้จักกับ MLI",description:[b]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"จ่ายน้อยกว่า เพื่อคุณภาพที่ดีกว่า",description:["เราให้ความสำคัญ 2 ประการคือ \"คุณภาพการศึกษา\" และ \"ราคา\"","ภาษาอังกฤษเป็นภาษาสากลและเป็นเครื่องมือที่จำเป็นสำหรับการสื่อสารกับผู้คนจากทั่วโลก เราหวังว่านักเรียนต่างชาติจะได้เรียนรู้ทักษะภาษาอังกฤษเพื่อประสบความสำเร็จ ด้วยเหตุนี้เราจึงมุ่งเน้นไปที่คุณภาพของชั้นเรียนกับราคาที่เหมาะสม"]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"ปัจจุบัน มีนักเรียนมากกว่า 17,000 คนที่จบการศึกษาจาก MLI",description:["เราเปิดสอน หลักสูตร ESL (หลักสูตรภาษาอังกฤษทั่วไป 6 ทักษะ ได้แก่ ไวยากรณ์ การเขียน การอ่าน การฟัง การพูดและคำศัพท์) หลักสูตร TOEFL®, IELTS ™ (สำหรับนักเรียนที่ต้องการเข้าเรียนที่วิทยาลัย) และ TOEIC® ","มีนักเรียนจำนวนมาก ได้เข้าศึกษาต่อที่มหาวิทยาลัยหรือวิทยาลัยในสหรัฐฯ เช่น UCLA, USC และ Santa Monica College"],lists:[{link:"\u002Fth\u002Ffeature",image:a,text:"5 เหตุผลที่ควรเลือก MLI"},{link:"\u002Fth\u002Fcompany",image:a,text:"ข้อมูลบริษัท"},{link:"\u002Fth\u002Fimage-gallery",image:a,text:"คลังรูปภาพ\u002Fวิดีโอ"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:28.463Z",updatedAt:"2025-05-26T12:06:27.575Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg","MLI ก่อตั้งขึ้นในปี 2002 ซึ่งได้ตั้งอยู่บน 2 แหล่งยอดนิยมคือ Westwood และ Hollywood สถาบันได้ช่วยและส่งเสริมทักษะทางภาษาของนักเรียนจากทั่วโลก")));